"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Plus, X, Eye, EyeOff } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ExitAnimationItem {
  id: string;
  label: string;
  color: string;
}

const DEFAULT_TAGS: ExitAnimationItem[] = [
  { id: "1", label: "Components", color: "bg-pink-500" },
  { id: "2", label: "Motion Primitives", color: "bg-purple-500" },
  { id: "3", label: "Fluid Layout", color: "bg-indigo-500" },
  { id: "4", label: "Spring Physics", color: "bg-emerald-500" },
];

export function ExitAnimation({ className }: { className?: string }) {
  const [items, setItems] = useState<ExitAnimationItem[]>(DEFAULT_TAGS);
  const [mode, setMode] = useState<"popLayout" | "sync" | "wait">("popLayout");
  const [isBoxVisible, setIsBoxVisible] = useState(true);

  const handleRemove = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handleAdd = () => {
    const nextId = String(Date.now());
    const colors = ["bg-pink-500", "bg-purple-500", "bg-indigo-500", "bg-cyan-500", "bg-amber-500"];
    const randomColor = colors[Math.floor(Math.random() * colors.length)];
    setItems((prev) => [
      ...prev,
      { id: nextId, label: `Tag #${prev.length + 1}`, color: randomColor },
    ]);
  };

  return (
    <div
      data-slot="exit-animation"
      className={cn(
        "flex flex-col items-center justify-center gap-8 p-8 w-full max-w-lg mx-auto select-none rounded-3xl border border-neutral-200 bg-white dark:border-neutral-800 dark:bg-neutral-950 shadow-2xl",
        className
      )}
    >
      {/* Mode Selector Tabs */}
      <div className="flex items-center gap-1.5 p-1 rounded-2xl bg-neutral-100 dark:bg-neutral-800">
        {(["popLayout", "sync", "wait"] as const).map((m) => (
          <button
            key={m}
            type="button"
            onClick={() => setMode(m)}
            className={cn(
              "rounded-xl px-3 py-1.5 text-xs font-mono font-bold transition-colors cursor-pointer",
              mode === m
                ? "bg-white text-neutral-900 shadow-xs dark:bg-neutral-900 dark:text-neutral-100"
                : "text-neutral-500 hover:text-neutral-900 dark:hover:text-neutral-100"
            )}
          >
            {m}
          </button>
        ))}
      </div>

      {/* Hero Interactive Box */}
      <div className="flex flex-col items-center gap-3">
        <div className="h-28 w-28 flex items-center justify-center">
          <AnimatePresence initial={false} mode={mode}>
            {isBoxVisible ? (
              <motion.div
                key="box"
                layout
                initial={{ opacity: 0, scale: 0.3, rotate: -15 }}
                animate={{ opacity: 1, scale: 1, rotate: 0 }}
                exit={{ opacity: 0, scale: 0.3, rotate: 15 }}
                transition={{ type: "spring", stiffness: 450, damping: 25 }}
                className="h-24 w-24 rounded-3xl bg-gradient-to-tr from-pink-500 to-purple-600 shadow-xl flex items-center justify-center text-white font-black text-sm"
              >
                MOTION
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>

        <button
          type="button"
          onClick={() => setIsBoxVisible(!isBoxVisible)}
          className="flex items-center gap-2 rounded-full border border-neutral-200 bg-neutral-50 px-4 py-1.5 text-xs font-semibold text-neutral-700 transition-colors hover:bg-neutral-100 dark:border-neutral-800 dark:bg-neutral-900 dark:text-neutral-300 dark:hover:bg-neutral-800 cursor-pointer"
        >
          {isBoxVisible ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
          <span>{isBoxVisible ? "Trigger Exit" : "Trigger Enter"}</span>
        </button>
      </div>

      {/* Tag List with PopLayout Exit Animation */}
      <div className="w-full flex flex-col items-center gap-3">
        <div className="flex items-center justify-between w-full px-2">
          <span className="text-xs font-mono text-neutral-500 font-semibold">
            Interactive List (mode: {mode})
          </span>
          <button
            type="button"
            onClick={handleAdd}
            className="flex items-center gap-1 text-xs font-bold text-pink-500 hover:underline cursor-pointer"
          >
            <Plus className="h-3.5 w-3.5" />
            <span>Add Item</span>
          </button>
        </div>

        <motion.ul
          layout
          className="relative flex flex-wrap gap-2 justify-center w-full min-h-[44px] p-2"
        >
          <AnimatePresence mode={mode}>
            {items.map((item) => (
              <motion.li
                key={item.id}
                layout
                initial={{ opacity: 0, scale: 0.5, y: 10 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.5, y: -10 }}
                transition={{ type: "spring", stiffness: 500, damping: 30 }}
                className={cn(
                  "flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold text-white shadow-xs",
                  item.color
                )}
              >
                <span>{item.label}</span>
                <button
                  type="button"
                  onClick={() => handleRemove(item.id)}
                  className="rounded-full hover:bg-black/20 p-0.5 cursor-pointer"
                >
                  <X className="h-3 w-3" />
                </button>
              </motion.li>
            ))}
          </AnimatePresence>
        </motion.ul>
      </div>
    </div>
  );
}
